  deleteSelected: document.querySelector('#delete-selected'),
  collectionView: document.querySelector('#collection-view'),
  bookmarkDialog: document.querySelector('#bookmark-dialog'),
  bookmarkForm: document.querySelector('#bookmark-form'),
  bookmarkName: document.querySelector('#bookmark-name'),
  bookmarkUrl: document.querySelector('#bookmark-url'),
  bookmarkNameError: document.querySelector('#bookmark-name-error'),
  bookmarkUrlError: document.querySelector('#bookmark-url-error'),
  duplicateBookmarkError: document.querySelector('#duplicate-bookmark-error'),
  organizeDialog: document.querySelector('#organize-dialog'),
  organizeForm: document.querySelector('#organize-form'),
  organizeCopy: document.querySelector('#organize-dialog-copy'),
  destinationList: document.querySelector('#destination-list'),
  newCollectionField: document.querySelector('#new-collection-field'),
  collectionName: document.querySelector('#collection-name'),
  collectionNameError: document.querySelector('#collection-name-error'),
  duplicateCollectionError: document.querySelector('#duplicate-collection-error'),
  organizeSubmit: document.querySelector('#organize-submit'),
  deleteDialog: document.querySelector('#delete-dialog'),
  deleteTitle: document.querySelector('#delete-dialog-title'),
  deleteCopy: document.querySelector('#delete-dialog-copy'),
  cancelDelete: document.querySelector('#cancel-delete'),
  confirmDelete: document.querySelector('#confirm-delete'),
  toast: document.querySelector('#toast'),
  toastMessage: document.querySelector('#toast-message')
};

function plural(count, singular, pluralForm = `${singular}s`) {
  return `${count} ${count === 1 ? singular : pluralForm}`;
}

function escapeText(value) {
  const span = document.createElement('span');
  span.textContent = value;
  return span.innerHTML;
}

function collectionFor(bookmark) {
  return state.collections.find((collection) => collection.id === bookmark.collectionId) ?? null;
}

function persist() {
  saveState(state);
}

function showToast(message) {
  clearTimeout(toastTimer);
  elements.toastMessage.textContent = message;
  elements.toast.classList.add('visible');
  toastTimer = setTimeout(() => elements.toast.classList.remove('visible'), 3200);
}

function setFieldError(input, target, message) {
  input.setAttribute('aria-invalid', message ? 'true' : 'false');
  target.textContent = message || '';
  target.classList.toggle('visible', Boolean(message));
}

function setAlert(target, message) {
  target.textContent = message || '';
  target.classList.toggle('visible', Boolean(message));
}

function clearBookmarkErrors() {
  setFieldError(elements.bookmarkName, elements.bookmarkNameError, '');
  setFieldError(elements.bookmarkUrl, elements.bookmarkUrlError, '');
  setAlert(elements.duplicateBookmarkError, '');
}

function clearCollectionErrors() {
  setFieldError(elements.collectionName, elements.collectionNameError, '');
  setAlert(elements.duplicateCollectionError, '');
}

function openBookmarkForm() {
  elements.bookmarkForm.reset();
  clearBookmarkErrors();
  elements.bookmarkDialog.showModal();
  elements.bookmarkName.focus();
}

function renderFilters() {
  elements.filters.replaceChildren();
  const choices = [{ id: 'all', name: 'All', count: state.bookmarks.length }, ...state.collections.map((collection) => ({
    ...collection,
    count: state.bookmarks.filter((bookmark) => bookmark.collectionId === collection.id).length
  }))];

  choices.forEach((choice) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'filter-button';
    button.dataset.collectionId = choice.id;
    button.setAttribute('aria-pressed', String(view.collectionId === choice.id));
    button.innerHTML = `${escapeText(choice.name)} <span class="filter-count">${choice.count}</span>`;
    button.addEventListener('click', () => {
      view.collectionId = choice.id;
      render();
    });
    elements.filters.appendChild(button);
  });
}

function createCard(bookmark) {
  const collection = collectionFor(bookmark);
  const card = document.createElement('article');
  card.className = `bookmark-card${view.selected.has(bookmark.id) ? ' selected' : ''}`;
  card.dataset.bookmarkId = bookmark.id;
  card.dataset.bookmarkName = bookmark.name;
  card.tabIndex = 0;
  card.setAttribute('role', 'link');
  card.setAttribute('aria-label', `Open ${bookmark.name} in a new tab`);
  card.innerHTML = `
    <input class="card-checkbox" type="checkbox" ${view.selected.has(bookmark.id) ? 'checked' : ''} aria-label="Select ${escapeText(bookmark.name)}">
    <div class="site-letter" aria-hidden="true">${escapeText(bookmark.name.slice(0, 1) || '↗')}</div>
    <div class="card-copy">
      <p class="bookmark-name" title="${escapeText(bookmark.name)}">${escapeText(bookmark.name)}</p>
      <p class="bookmark-url" title="${escapeText(bookmark.url)}">${escapeText(bookmark.url)}</p>
      <span class="collection-tag ${collection ? '' : 'unfiled-tag'}" title="${escapeText(collection?.name || 'Unfiled')}">${escapeText(collection?.name || 'Unfiled')}</span>
    </div>
    <button class="delete-card" type="button" aria-label="Delete ${escapeText(bookmark.name)}">
      <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3m-9 0 1 13h10l1-13M10 11v5m4-5v5"></path></svg>
    </button>`;

  const checkbox = card.querySelector('.card-checkbox');
  checkbox.addEventListener('click', (event) => event.stopPropagation());
  checkbox.addEventListener('change', () => {
    if (checkbox.checked) view.selected.add(bookmark.id);
    else view.selected.delete(bookmark.id);
    render();
  });

  const deleteButton = card.querySelector('.delete-card');
  deleteButton.addEventListener('click', (event) => {
    event.stopPropagation();
    openDeleteConfirmation([bookmark.id]);
  });

  const open = () => window.open(bookmark.url, '_blank', 'noopener,noreferrer');
  card.addEventListener('click', (event) => {
    if (!event.target.closest('button, input')) open();
  });
  card.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' && event.target === card) {
      event.preventDefault();
      open();
    }
  });
  return card;
}

function createSection(title, bookmarks, named = false) {
  const section = document.createElement('section');
  section.className = `collection-section${named ? ' named' : ''}`;
  const heading = document.createElement('div');
  heading.className = 'section-heading';
  heading.innerHTML = `<h3>${escapeText(title)}</h3><span>${plural(bookmarks.length, 'bookmark')}</span>`;
  const grid = document.createElement('div');
  grid.className = 'card-grid';
  bookmarks.forEach((bookmark) => grid.appendChild(createCard(bookmark)));
  section.append(heading, grid);
  return section;
}

function renderEmptyState() {
  elements.collectionView.innerHTML = `
    <section class="empty-state">
      <div>
        <div class="empty-illustration" aria-hidden="true"></div>
        <h2>Your collection is empty</h2>
        <p>Save a useful page whenever you find one. It’ll be waiting here when you need it again.</p>
        <button class="button button-primary" id="add-first-bookmark" type="button">Add your first bookmark</button>
      </div>
    </section>`;
  document.querySelector('#add-first-bookmark').addEventListener('click', openBookmarkForm);
}

function renderNoResults() {
  const filter = state.collections.find((collection) => collection.id === view.collectionId);
  const context = filter
    ? `No saved link in ${filter.name} contains that text. Clear the search to return to the collection.`
    : 'Try a different word or clear the search to see your bookmarks again.';
  elements.collectionView.innerHTML = `
    <section class="no-results">
      <div>
        <div class="search-zero" aria-hidden="true">⌕</div>
        <h2>No bookmarks match that search</h2>
        <p>${escapeText(context)}</p>
        <button class="button button-secondary" id="clear-empty-search" type="button">Clear search</button>
      </div>
    </section>`;
  document.querySelector('#clear-empty-search').addEventListener('click', () => {
    view.search = '';
    elements.search.value = '';
    render();
  });
}

function renderBookmarkList(matches) {
  const filter = state.collections.find((collection) => collection.id === view.collectionId);
  let title = 'All bookmarks';
  if (filter && view.search) title = `${filter.name} matching “${view.search}”`;
  else if (filter) title = filter.name;
  else if (view.search) title = `Results for “${view.search}”`;

  const heading = document.createElement('div');
  heading.className = 'view-heading';
  heading.innerHTML = `<h2>${escapeText(title)}</h2><span>${plural(matches.length, view.search || filter ? 'result' : 'bookmark')}</span>`;
  elements.collectionView.replaceChildren(heading);

  if (view.collectionId === 'all' && !view.search) {
    state.collections.forEach((collection) => {
      const grouped = matches.filter((bookmark) => bookmark.collectionId === collection.id);
      if (grouped.length) elements.collectionView.appendChild(createSection(collection.name, grouped, true));
    });
    const unfiled = matches.filter((bookmark) => !bookmark.collectionId);
    if (unfiled.length) elements.collectionView.appendChild(createSection('Unfiled', unfiled));
  } else {
    const grid = document.createElement('div');
    grid.className = 'card-grid';
    matches.forEach((bookmark) => grid.appendChild(createCard(bookmark)));
    elements.collectionView.appendChild(grid);
  }
}

function renderSelectionBar() {
  const count = view.selected.size;
  elements.selectionBar.hidden = count === 0;
  elements.selectionCount.textContent = plural(count, 'selected bookmark', 'selected bookmarks');
}

function render() {
  const existingIds = new Set(state.bookmarks.map((bookmark) => bookmark.id));
  view.selected = new Set([...view.selected].filter((id) => existingIds.has(id)));
  if (view.collectionId !== 'all' && !state.collections.some((collection) => collection.id === view.collectionId)) {
    view.collectionId = 'all';
  }

  elements.totalNumber.textContent = state.bookmarks.length;
  elements.totalLabel.textContent = state.bookmarks.length === 1 ? 'bookmark' : 'bookmarks';
  elements.finder.hidden = state.bookmarks.length === 0;
  renderSelectionBar();
  renderFilters();

  if (state.bookmarks.length === 0) {
    renderEmptyState();
  } else {
    const matches = findBookmarks(state, { search: view.search, collectionId: view.collectionId });
    if (matches.length === 0 && view.search) renderNoResults();
    else renderBookmarkList(matches);
  }
  elements.shell.setAttribute('data-harness-ready', 'true');
}

function renderDestinationChoices() {
  elements.destinationList.replaceChildren();
  state.collections.forEach((collection, index) => {
    const count = state.bookmarks.filter((bookmark) => bookmark.collectionId === collection.id).length;
    const label = document.createElement('label');
    label.className = 'destination-option';
    label.innerHTML = `
      <input type="radio" name="destination" value="${escapeText(collection.id)}" ${index === 0 ? 'checked' : ''}>
      <span class="destination-name" title="${escapeText(collection.name)}">${escapeText(collection.name)}</span>
      <span class="destination-count">${plural(count, 'bookmark')}</span>`;
    elements.destinationList.appendChild(label);
  });

  const newLabel = document.createElement('label');
  newLabel.className = 'destination-option';
  newLabel.innerHTML = `
    <input type="radio" name="destination" value="new" ${state.collections.length === 0 ? 'checked' : ''}>
    <span class="destination-name">Create a new collection</span>
    <span class="destination-count">New</span>`;
  elements.destinationList.appendChild(newLabel);

  elements.destinationList.querySelectorAll('input').forEach((input) => input.addEventListener('change', updateDestinationState));
  updateDestinationState();
}

function updateDestinationState() {
  const selected = elements.organizeForm.elements.destination?.value;
  const isNew = selected === 'new';
  elements.collectionName.disabled = !isNew;
  elements.newCollectionField.classList.toggle('inactive', !isNew);
  elements.organizeSubmit.textContent = isNew ? 'Create collection' : 'Add to collection';
  clearCollectionErrors();
}

function openOrganizeDialog() {
  if (!view.selected.size) return;
  elements.organizeForm.reset();
  clearCollectionErrors();
  elements.organizeCopy.textContent = `${plural(view.selected.size, 'selected bookmark')} will be kept together.`;
  renderDestinationChoices();
  elements.organizeDialog.showModal();
  if (!state.collections.length) elements.collectionName.focus();
}

function openDeleteConfirmation(ids) {
  view.pendingDelete = ids.filter((id) => state.bookmarks.some((bookmark) => bookmark.id === id));
  if (!view.pendingDelete.length) return;
  const selectedBookmarks = state.bookmarks.filter((bookmark) => view.pendingDelete.includes(bookmark.id));
  if (selectedBookmarks.length === 1) {
    elements.deleteTitle.textContent = 'Delete this bookmark?';
    elements.deleteCopy.textContent = `“${selectedBookmarks[0].name}” will be permanently removed from your collection.`;
    elements.confirmDelete.textContent = 'Delete bookmark';
  } else {
    elements.deleteTitle.textContent = `Delete ${selectedBookmarks.length} bookmarks?`;
    elements.deleteCopy.textContent = 'The selected bookmarks will be permanently removed from your collection.';
    elements.confirmDelete.textContent = `Delete ${selectedBookmarks.length} bookmarks`;
  }
  elements.deleteDialog.showModal();
  elements.cancelDelete.focus();
}

elements.addTop.addEventListener('click', openBookmarkForm);
document.querySelectorAll('.close-dialog').forEach((button) => button.addEventListener('click', () => elements.bookmarkDialog.close()));
document.querySelectorAll('.close-organize').forEach((button) => button.addEventListener('click', () => elements.organizeDialog.close()));

elements.bookmarkForm.addEventListener('submit', (event) => {
  event.preventDefault();
  clearBookmarkErrors();
  const result = addBookmark(state, { name: elements.bookmarkName.value, url: elements.bookmarkUrl.value });
  if (Object.keys(result.errors).length) {
    setFieldError(elements.bookmarkName, elements.bookmarkNameError, result.errors.name);
    setFieldError(elements.bookmarkUrl, elements.bookmarkUrlError, result.errors.url);
    setAlert(elements.duplicateBookmarkError, result.errors.duplicate);
    (result.errors.name ? elements.bookmarkName : elements.bookmarkUrl).focus();
    return;
  }
  state = result.state;
  persist();
  elements.bookmarkDialog.close();
  render();
  showToast('Bookmark saved to your collection');
});

elements.search.addEventListener('input', (event) => {
  view.search = event.target.value.trim();
  render();
});

elements.clearSelection.addEventListener('click', () => {
  view.selected.clear();
  render();
});
elements.organizeSelected.addEventListener('click', openOrganizeDialog);
elements.deleteSelected.addEventListener('click', () => openDeleteConfirmation([...view.selected]));

elements.organizeForm.addEventListener('submit', (event) => {
  event.preventDefault();
  clearCollectionErrors();
  const destination = elements.organizeForm.elements.destination.value;
  const selectedIds = [...view.selected];
  let collectionName;
  if (destination === 'new') {
    const result = createCollectionAndAssign(state, elements.collectionName.value, selectedIds);
    if (Object.keys(result.errors).length) {
      setFieldError(elements.collectionName, elements.collectionNameError, result.errors.name);
      setAlert(elements.duplicateCollectionError, result.errors.duplicate);
      elements.collectionName.focus();
      return;
    }
    state = result.state;
    collectionName = result.collection.name;
  } else {
    const collection = state.collections.find((item) => item.id === destination);
    if (!collection) return;
    state = assignToCollection(state, destination, selectedIds);
    collectionName = collection.name;
  }
  persist();
  view.selected.clear();
  elements.organizeDialog.close();
  render();
  showToast(`Added to ${collectionName}`);
});

elements.cancelDelete.addEventListener('click', () => {
  view.pendingDelete = [];
  elements.deleteDialog.close();
});

elements.confirmDelete.addEventListener('click', () => {
  const amount = view.pendingDelete.length;
  state = deleteBookmarks(state, view.pendingDelete);
  view.pendingDelete.forEach((id) => view.selected.delete(id));
  view.pendingDelete = [];
  persist();
  elements.deleteDialog.close();
  render();
  showToast(amount === 1 ? 'Bookmark deleted' : `${amount} bookmarks deleted`);
});

render();

/work/implementation/public/styles.css.content:
:root {
  --ink: #17211d;
  --muted: #68746f;
  --paper: #f5f3ed;
  --surface: #fffefb;
  --line: #dcded7;
  --line-strong: #c8ccc3;
  --teal: #145f57;
  --teal-deep: #0b4640;
  --teal-soft: #dfefeb;
  --coral: #a84438;
  --coral-deep: #87352c;
  --coral-soft: #f8e8e4;
  --gold-soft: #f4ebce;
  --shadow-sm: 0 5px 18px rgba(27, 39, 34, .06);
  --shadow-lg: 0 24px 70px rgba(26, 37, 32, .18);
}

* { box-sizing: border-box; }

html { min-width: 320px; }

body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  background:
    radial-gradient(circle at 8% 4%, rgba(188, 220, 208, .48), transparent 27rem),
    radial-gradient(circle at 94% 16%, rgba(244, 226, 187, .36), transparent 24rem),
    var(--paper);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

button, input { font: inherit; }
button { color: inherit; }

.app-shell {
  width: min(1160px, calc(100% - 48px));
  margin: 0 auto;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 88px;
  border-bottom: 1px solid rgba(91, 106, 99, .2);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: var(--ink);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -.02em;
  text-decoration: none;
}

.brand-symbol {
  position: relative;
  display: grid;
  place-items: center;
  width: 35px;
  height: 39px;
  background: var(--teal);
  border-radius: 6px 6px 3px 3px;
}

.brand-symbol::after {
  position: absolute;
  bottom: -1px;
  left: 8px;
  width: 19px;
  height: 11px;
  background: var(--paper);
  clip-path: polygon(0 100%, 50% 0, 100% 100%);
  content: "";
}

.brand-symbol span {
  width: 15px;
  border-top: 2px solid white;
  border-bottom: 2px solid white;
  height: 8px;
  transform: translateY(-3px);
}

main { padding: 68px 0 100px; }

.hero { margin-bottom: 46px; }
.kicker, .dialog-kicker {
  margin: 0 0 9px;
  color: var(--teal);
  font-size: 12px;
  font-weight: 850;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.hero-row {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 40px;
}

h1 {
  margin: 0;
  font: 500 clamp(39px, 5vw, 58px)/1.04 Georgia, "Times New Roman", serif;
  letter-spacing: -.045em;
}

.hero-copy {
  max-width: 700px;
  margin: 17px 0 0;
  color: var(--muted);
  font-size: 17px;
  line-height: 1.6;
}

.total-count {
  display: grid;
  min-width: 116px;
  padding: 15px 18px;
  text-align: right;
  background: rgba(255, 254, 251, .66);
  border: 1px solid var(--line);
  border-radius: 15px;
}

.total-count strong { font: 600 30px/1 Georgia, serif; }
.total-count span { margin-top: 5px; color: var(--muted); font-size: 12px; font-weight: 750; }

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 42px;
  padding: 10px 15px;
  border: 1px solid transparent;
  border-radius: 11px;
  cursor: pointer;
  font-weight: 780;
}

.button-primary { color: white; background: var(--teal); box-shadow: 0 7px 18px rgba(20, 95, 87, .18); }
.button-primary:hover { background: var(--teal-deep); }
.button-secondary { background: var(--surface); border-color: var(--line-strong); }
.button-secondary:hover { background: #f6f6f1; }
.button-danger { color: white; background: var(--coral); }
.button-danger:hover { background: var(--coral-deep); }
.button-danger-quiet { color: var(--coral); background: var(--surface); border-color: #e7c7c1; }
.button-danger-quiet:hover { background: var(--coral-soft); }

button:focus-visible, input:focus-visible, [role="link"]:focus-visible {
  outline: 3px solid rgba(20, 95, 87, .22);
  outline-offset: 2px;
}

.finder {
  display: grid;
  gap: 13px;
  margin-bottom: 30px;
}

.finder[hidden], .selection-bar[hidden] { display: none; }

.search-box { position: relative; display: block; }
.search-box svg {
  position: absolute;
  top: 50%;
  left: 17px;
  width: 21px;
  fill: none;
  stroke: var(--muted);
  stroke-linecap: round;
  stroke-width: 1.8;
  transform: translateY(-50%);
}

.search-box input {
  width: 100%;
  height: 54px;
  padding: 0 18px 0 50px;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: 14px;
  box-shadow: var(--shadow-sm);
}

.filter-strip { display: flex; gap: 8px; overflow-x: auto; padding: 2px 1px 4px; }
.filter-button {
  flex: none;
  padding: 8px 12px;
  color: var(--muted);
  background: rgba(255, 254, 251, .74);
  border: 1px solid var(--line);
  border-radius: 999px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 780;
  white-space: nowrap;
}
.filter-button[aria-pressed="true"] { color: white; background: var(--teal); border-color: var(--teal); }
.filter-count { margin-left: 5px; opacity: .75; }

.selection-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 20px;
  padding: 12px 14px 12px 17px;
  color: var(--teal-deep);
  background: var(--teal-soft);
  border: 1px solid #bfd9d2;
  border-radius: 14px;
}
.selection-bar > div { display: flex; align-items: center; gap: 11px; }
.selection-bar strong { font-size: 14px; }
.text-button { padding: 4px; color: var(--teal); background: transparent; border: 0; cursor: pointer; font-size: 13px; text-decoration: underline; }
.selection-actions { margin-left: auto; }

.collection-view { min-height: 280px; }
.view-heading { display: flex; align-items: end; justify-content: space-between; gap: 20px; margin-bottom: 16px; }
.view-heading h2 { margin: 0; font: 600 25px/1.2 Georgia, serif; }
.view-heading span { color: var(--muted); font-size: 13px; font-weight: 700; }

.collection-section { margin-top: 30px; }
.collection-section:first-of-type { margin-top: 0; }
.section-heading { display: flex; align-items: center; justify-content: space-between; margin: 0 2px 12px; }
.section-heading h3 { margin: 0; font: 600 18px/1.2 Georgia, serif; }
.section-heading span { color: var(--muted); font-size: 12px; font-weight: 700; }
.collection-section.named { padding: 17px; background: rgba(223, 239, 235, .48); border: 1px solid #c8ddd7; border-radius: 19px; }

.card-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 11px; }
.bookmark-card {
  position: relative;
  display: grid;
  grid-template-columns: 24px 46px minmax(0, 1fr) 38px;
  align-items: center;
  gap: 13px;
  min-width: 0;
  padding: 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 15px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: border-color .15s ease, box-shadow .15s ease, transform .15s ease;
}
.bookmark-card:hover { border-color: #9fb9b0; box-shadow: 0 9px 25px rgba(27, 39, 34, .1); transform: translateY(-1px); }
.bookmark-card.selected { border-color: #76a79e; box-shadow: 0 0 0 2px rgba(20, 95, 87, .12); }
.card-checkbox { width: 18px; height: 18px; margin: 0; accent-color: var(--teal); cursor: pointer; }
.site-letter { display: grid; place-items: center; width: 44px; height: 44px; color: var(--teal); background: var(--teal-soft); border-radius: 12px; font: 700 18px/1 Georgia, serif; text-transform: uppercase; }
.card-copy { min-width: 0; }
.bookmark-name { display: -webkit-box; overflow: hidden; margin: 0 0 4px; font-size: 15px; font-weight: 820; line-height: 1.3; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.bookmark-url { overflow: hidden; margin: 0 0 8px; color: var(--muted); font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }
.collection-tag { display: block; overflow: hidden; width: max-content; max-width: 100%; padding: 4px 8px; color: var(--teal); background: var(--teal-soft); border-radius: 999px; font-size: 10px; font-weight: 820; text-overflow: ellipsis; white-space: nowrap; }
.unfiled-tag { color: #735b22; background: var(--gold-soft); }
.delete-card { position: relative; z-index: 2; display: grid; place-items: center; width: 36px; height: 36px; color: var(--muted); background: transparent; border: 1px solid transparent; border-radius: 10px; cursor: pointer; }
.delete-card:hover { color: var(--coral); background: var(--coral-soft); border-color: #eccbc5; }
.delete-card svg { width: 17px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.8; }

.empty-state, .no-results {
  display: grid;
  place-items: center;
  min-height: 330px;
  padding: 44px 24px;
  text-align: center;
  background: rgba(255, 254, 251, .72);
  border: 1px solid var(--line);
  border-radius: 20px;
}
.empty-illustration { position: relative; width: 72px; height: 65px; margin: 0 auto 21px; }
.empty-illustration::before, .empty-illustration::after { position: absolute; content: ""; }
.empty-illustration::before { inset: 6px 13px 0; background: var(--teal-soft); border: 2px solid var(--teal); border-radius: 8px 8px 4px 4px; }
.empty-illustration::after { bottom: -1px; left: 25px; width: 22px; height: 16px; background: var(--surface); clip-path: polygon(0 100%, 50% 0, 100% 100%); }
.empty-state h2, .no-results h2 { margin: 0 0 8px; font: 600 23px/1.2 Georgia, serif; }
.empty-state p, .no-results p { max-width: 470px; margin: 0 0 22px; color: var(--muted); line-height: 1.55; }
.no-results .search-zero { display: grid; place-items: center; width: 58px; height: 58px; margin-bottom: 19px; color: var(--teal); background: var(--teal-soft); border-radius: 50%; font-size: 26px; }

.dialog {
  width: min(520px, calc(100% - 28px));
  padding: 28px;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 20px;
  box-shadow: var(--shadow-lg);
}
.dialog::backdrop { background: rgba(18, 30, 26, .5); backdrop-filter: blur(4px); }
.dialog-compact { width: min(450px, calc(100% - 28px)); }
.dialog-header { display: flex; align-items: start; justify-content: space-between; gap: 20px; }
.dialog h2 { margin: 0; font: 600 27px/1.15 Georgia, serif; }
.dialog-intro { margin: 9px 0 23px; color: var(--muted); font-size: 14px; line-height: 1.55; }
.icon-button { display: grid; place-items: center; width: 34px; height: 34px; color: var(--muted); background: transparent; border: 1px solid var(--line); border-radius: 9px; cursor: pointer; font-size: 22px; line-height: 1; }
.field { margin-top: 17px; }
.field label { display: block; margin-bottom: 7px; font-size: 13px; font-weight: 820; }
.field input { width: 100%; height: 47px; padding: 0 13px; color: var(--ink); background: white; border: 1px solid var(--line-strong); border-radius: 10px; }
.field input[aria-invalid="true"] { border-color: var(--coral); box-shadow: 0 0 0 3px rgba(168, 68, 56, .1); }
.field-error { display: none; margin: 7px 0 0; color: var(--coral); font-size: 12px; font-weight: 730; }
.field-error.visible { display: block; }
.form-alert { display: none; margin-top: 15px; padding: 12px 13px; color: #73332b; background: var(--coral-soft); border: 1px solid #edcbc4; border-radius: 10px; font-size: 13px; line-height: 1.45; }
.form-alert.visible { display: block; }
.dialog-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 27px; }

.destination-list { display: grid; gap: 8px; margin: 0; padding: 0; border: 0; }
.destination-option { display: grid; grid-template-columns: 20px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 12px 13px; background: #fafaf6; border: 1px solid var(--line); border-radius: 11px; cursor: pointer; }
.destination-option:has(input:checked) { background: var(--teal-soft); border-color: #9dc4bb; }
.destination-option input { width: 16px; height: 16px; accent-color: var(--teal); }
.destination-name { overflow: hidden; font-size: 13px; font-weight: 820; text-overflow: ellipsis; white-space: nowrap; }
.destination-count { color: var(--muted); font-size: 11px; font-weight: 700; }
.new-collection-field { margin-left: 30px; }
.new-collection-field.inactive { opacity: .58; }
.danger-symbol { display: grid; place-items: center; width: 48px; height: 48px; margin-bottom: 18px; color: var(--coral); background: var(--coral-soft); border-radius: 14px; font-size: 22px; font-weight: 900; }

.toast { position: fixed; right: 25px; bottom: 25px; z-index: 20; display: flex; align-items: center; gap: 10px; max-width: min(400px, calc(100% - 30px)); padding: 14px 17px; color: white; background: var(--teal-deep); border-radius: 12px; box-shadow: 0 14px 38px rgba(11, 70, 64, .3); font-size: 14px; font-weight: 760; opacity: 0; pointer-events: none; transform: translateY(10px); transition: opacity .18s ease, transform .18s ease; }
.toast.visible { opacity: 1; transform: translateY(0); }
.toast-check { display: grid; place-items: center; width: 22px; height: 22px; color: var(--teal-deep); background: white; border-radius: 50%; font-size: 13px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

@media (max-width: 760px) {
  .app-shell { width: min(100% - 28px, 1160px); }
  .topbar { min-height: 78px; }
  main { padding-top: 48px; }
  .hero-row { align-items: start; flex-direction: column; gap: 22px; }
  .total-count { text-align: left; }
  .card-grid { grid-template-columns: 1fr; }
}

@media (max-width: 560px) {
  .topbar .button { width: 42px; padding: 0; font-size: 0; }
  .topbar .button span { font-size: 21px; }
  .selection-bar { align-items: stretch; flex-direction: column; }
  .selection-actions { width: 100%; margin-left: 0; }
  .selection-actions .button { flex: 1; }
  .bookmark-card { grid-template-columns: 23px 42px minmax(0, 1fr) 34px; gap: 9px; padding: 13px; }
  .site-letter { width: 40px; height: 40px; }
  .dialog { padding: 22px; }
}

